export const scopeActionDefinitions=freezeProtocolValue({"AttachActivityScope":{"name":"AttachActivityScope","version":"3.0.0","input":"types.v1.json#/definitions/AttachActivityScopeInputV3","operation":"TeacherPrerequisiteApplication.attachActivityScope -> appendActivityScope, entityKey=null,expectedRevisionId=null","preconditions":["Actual verified current owner/session and ACTIVE dated self Teacher binding; exact pinned source/activity/student/class/lesson/date relations under the native owner gate.","Payload schema2,state ACTIVE; no existing ACTIVE attachment and no terminal guard for the same full scoped activity identity. No field/body supplies authority."],"effect":"One existing allocated scope:<uuid> key and one immutable initial schema2 ACTIVE owner revision through existing admission/idempotency/native transaction. Real native allocation only; no new allocator.","result":"Existing NativeWriteResult and native-commit-receipt.v1; scope changed from ABSENT to real revision; relation changed from ABSENT to real revision.","errors":"Current auth/binding refusals precede target detail; authorized invalid payload400, wrong action version/definition409, duplicate/terminal attachment409, exact source revision409. Ambiguous effect remains lookup-only, never a terminal refusal.","semantics":"semantics.v1.json#/G4"},"CorrectActivityScope":{"name":"CorrectActivityScope","version":"3.0.0","input":"types.v1.json#/definitions/CorrectActivityScopeInputV3","operation":"TeacherPrerequisiteApplication.correctActivityScope -> existing appendActivityScope, exact same nonnull scopeKey+expectedRevisionId","branches":{"ACTIVE":"Explicit existing CAS retarget/correction from a validated ACTIVE head only; dated teacher/ref/identity checks and immutable history remain.","DETACHED":"ACTIVE->DETACHED exactly once; same activityKind/exact activityRef/recordScope/sourceLiteral/synthetic, append terminal native revision and keep source/history unchanged."},"terminalGuard":"No correction/new attach for the same scoped activity identity after DETACHED; changing source revision or allocated scope key cannot bypass the terminal guard. No reattach policy.","receipt":"Scope row after=terminal OWNER_REVISION; changedLinks has the original scope relation endpoints and native key, before=exact prior OWNER_REVISION, after=ABSENT. The immutable row is retained.","errors":{"activity_scope_terminal":"409, authorized terminal predecessor or reattachment attempt","activity_scope_terminal_payload_changed":"409, authorized detach changes retained lineage","activity_scope_action_version":"409, authorized wrong action name/version/definition or legacy mutation protocol","stale_base":"409, exact current scope CAS mismatch; preserve existing source code where this is the native terminal refusal","invalid_activity_scope":"400, authorized closed schema/discriminant failure","existingRightsAndUnknowns":"Existing401/403 precedence and native outcome lookup/fence/unknown-no-replay rules unchanged."},"semantics":"semantics.v1.json#/G4"},"ScopeRelation":{"contract":"native-prerequisite-scope-relation.v4","version":"4.0.0","kind":"activity_scope","nativeIdentity":"Actual same owner/scope/namespace scope entityKey","from":"Actual activityRef native identity","to":"Retained recordScope.lessonRef native identity","states":{"ACTIVE":"Relation present at exact immutable scope revision","DETACHED":"Relation ABSENT; immutable terminal scope revision remains"},"legacyRead":"Validated exact six-key legacy row is ACTIVE in memory. Its original payload, history and historical receipts remain unchanged. New action receipt binds this successor relation definition and the exact prior native revision; it does not rewrite a legacy receipt.","rules":"Only active heads participate in scope qualification/active uniqueness/approval edges. Terminal heads and history participate in horizon and no-reattach guard. Three derived activity links are not three independent persisted relations."}} as const);
export type ActivityScopeLinkV2=ActivityScopeLink&{schemaVersion:'2.0.0';state:'ACTIVE'|'DETACHED'};
/** Legacy rows remain untouched; only validated exact six-key rows normalize as ACTIVE. */
export function activityScopeState(payload:ActivityScopeLink):'ACTIVE'|'DETACHED'{validateOwnerPayload(payload);return payload.state??'ACTIVE';}
export function validateScopeMutation(payload:ActivityScopeLink,action:ActionBinding,correction:boolean):asserts payload is ActivityScopeLinkV2{
 validateOwnerPayload(payload);
 if(payload.schemaVersion!=='2.0.0'||!Object.hasOwn(payload,'state'))throw Error('activity_scope_action_version');
 const definition=scopeActionDefinitions[correction?'CorrectActivityScope':'AttachActivityScope'];
 if(action.name!==definition.name||action.version!==definition.version||action.definitionSha256!==digest(definition))throw Error('activity_scope_action_version');
 if(!correction&&payload.state!=='ACTIVE')throw Error('activity_scope_terminal');
}
export function fixedConsumerProfile(profile:ConsumerProfileId){
 if(profile!=='CURRENT_1_1'&&profile!=='OLD_SECTION_1_0')throw Error('invalid_consumer_profile');
 const definition=consumerProfileDefinitions[profile],pins=consumerProfilePins[profile];
 if(digest(definition)!==pins.consumerProfileDigest)throw Error('consumer_profile_definition_mismatch');
 return {id:profile,definition,pins};
}

/** Malformed nested input (e.g. null where an object is required) surfaces as TypeError inside a validator;
 * it is a caller input error, so it becomes the closed refusal invalid_prerequisite_shape (400). */
function shaped<A extends unknown[]>(validate:(...args:A)=>void):(...args:A)=>void{
 return (...args:A)=>{try{validate(...args);}catch(error){if(error instanceof TypeError)throw Error('invalid_prerequisite_shape');throw error;}};
}
export const validateNativeStudentPayload:(p:NativeStudentPayload)=>void=shaped(validateNativeStudentPayloadUnshaped);
export const validateOwnerPayload:(p:OwnerPayload)=>void=shaped(validateOwnerPayloadUnshaped);
export const validateContext:(c:CommandContext)=>void=shaped(validateContextUnshaped);

/** The one rule for which occurrence a progress/assessment (or homework/attempt) belongs to. Every reader
 * (read horizon, typed projection, approval closure) uses this instead of choosing between the embedded
 * payload scope and the activity-scope attachments itself:
 *  - no attachment for the activity: EMBEDDED (its payload scope), or UNRESOLVED when it has none;
 *  - a DETACHED attachment: DETACHED (withheld; the caller checks the pinned revision);
 *  - exactly one ACTIVE attachment pinning this exact revision: ATTACHED at that scope;
 *  - otherwise (stale pin, several ACTIVE): UNRESOLVED, never the embedded original. */
export type ActivityOccurrence=
 |{state:'EMBEDDED';scope:RecordScope;attachments:OwnerVersion<ActivityScopeLink>[]}
 |{state:'ATTACHED';scope:RecordScope;attachment:OwnerVersion<ActivityScopeLink>;attachments:OwnerVersion<ActivityScopeLink>[]}
 |{state:'DETACHED';attachment:OwnerVersion<ActivityScopeLink>;attachments:OwnerVersion<ActivityScopeLink>[]}
 |{state:'UNRESOLVED';attachments:OwnerVersion<ActivityScopeLink>[]};
export function resolveActivityOccurrence(activity:{objectType:string;nativeKey:string;revision:string},embedded:RecordScope|null,scopes:readonly OwnerVersion<ActivityScopeLink>[]):ActivityOccurrence{
 const attachments=scopes.filter(v=>v.payload.activityRef.identity.objectType===activity.objectType&&v.payload.activityRef.identity.nativeKey===activity.nativeKey);
 if(!attachments.length)return embedded?{state:'EMBEDDED',scope:embedded,attachments}:{state:'UNRESOLVED',attachments};
 const detached=attachments.find(v=>activityScopeState(v.payload)==='DETACHED');
 if(detached)return {state:'DETACHED',attachment:detached,attachments};
 const active=attachments.filter(v=>activityScopeState(v.payload)==='ACTIVE'&&v.payload.activityRef.revision===activity.revision);
 return active.length===1?{state:'ATTACHED',scope:active[0]!.payload.recordScope,attachment:active[0]!,attachments}:{state:'UNRESOLVED',attachments};
}
/** The one operation -> student-record payload kind table (create and correct routes). */
export const studentOperationKinds:Readonly<Record<string,NativeStudentPayload['kind']>>=Object.freeze({
 createProgress:'daily_progress',correctProgress:'daily_progress',
 createAssessment:'previous_homework_assessment',correctAssessment:'previous_homework_assessment',
 createDraft:'daily_record_draft',updateDraft:'daily_record_draft',
});
export function assertStudentOperationKind(operation:string,payload:unknown):void{
 const kind=studentOperationKinds[operation];
 if(kind&&(!payload||typeof payload!=='object'||(payload as {kind?:unknown}).kind!==kind))throw Error('invalid_student_payload_kind');
}

